 public static String texture(String n){return DATA.get(n).texture;}
 public static void apply(GeoModel<?> model,GeoBone bone){var m=DATA.get(bone.getName());if(m==null)return;
 int j=0;for(var cube:bone.getCubes()){var points=m.faces[j++];for(int qi=0;qi<cube.quads().length;qi++){var old=cube.quads()[qi];if(old==null)continue;var vertices=new GeoVertex[4];
 for(int k=0;k<4;k++){var a=points[k];vertices[k]=new GeoVertex(new Vector3f(-a[0]/16,a[1]/16,a[2]/16),a[3],a[4]);}
 var normal=new Vector3f(vertices[1].position()).sub(vertices[0].position()).cross(new Vector3f(vertices[2].position()).sub(vertices[0].position()));if(normal.lengthSquared()<1e-12f)normal.set(old.normal());else normal.normalize();var mid=new Vector3f();for(var v:vertices)mid.add(v.position());mid.div(4);if(m.solid)mid.sub(m.center);else mid.y=0;if(normal.dot(mid)<0)normal.negate();
 cube.quads()[qi]=new GeoQuad(vertices,normal,old.direction());}}
 }

